// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.sketch;

import static org.junit.jupiter.api.Assertions.assertAll;

import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.function.Executable;

/** Owns the background workers and mapped files of every estimator created by a test, including failed setup. */
abstract class AbstractSketchBasedJoinEstimatorTest {

	private final List<SketchBasedJoinEstimator> estimators = new ArrayList<>();

	final SketchBasedJoinEstimator createEstimator(SketchStatementSource source,
			SketchBasedJoinEstimator.Config config) {
		return trackEstimator(new SketchBasedJoinEstimator(source, config));
	}

	final <T extends SketchBasedJoinEstimator> T trackEstimator(T estimator) {
		estimators.add(estimator);
		return estimator;
	}

	final void closeEstimator(SketchBasedJoinEstimator estimator) {
		estimator.close();
		estimators.remove(estimator);
	}

	@AfterEach
	final void closeEstimators() {
		try {
			assertAll("close every test estimator", estimators.reversed()
					.stream()
					.map(estimator -> (Executable) estimator::close));
		} finally {
			estimators.clear();
		}
	}
}
